def _recheck_failed_acceptance_checks(
    self,
    failed_checks: list[dict[str, Any]],
) -> dict[str, Any]:
    """Verwirft False-Negatives nur mit validierter positiver Evidence aus derselben finalen Datei."""
    if self.reviewer_client is None or not failed_checks:
        return {
            "verdict": "FIX_REQUIRED",
            "summary": "Kein positiver Gegenbeleg verfügbar.",
            "checks": [],
        }

    final_files = self._acceptance_final_files()
    requested = [
        {
            "requirement": str(check.get("requirement", "")).strip(),
            "path": str(check.get("path", "")).strip(),
        }
        for check in failed_checks
        if str(check.get("requirement", "")).strip() and str(check.get("path", "")).strip()
    ]
    prompt = (
        "ORIGINALAUFTRAG:\n" + redact(self.state.task)
        + "\n\nZU PRÜFENDE BISHERIGE satisfied:false-CHECKS:\n"
        + json.dumps(failed_checks, ensure_ascii=False, indent=2)
        + "\n\nFINALER DATEISTAND GEÄNDERTER TEXTDATEIEN:\n"
        + self._acceptance_final_files_prompt(final_files)
        + "\n\nPrüfe ausschließlich die oben genannten negativen Checks erneut. "
        "Ein bisheriger satisfied:false-Check darf nur als False-Negative verworfen werden, "
        "wenn seine Anforderung im finalen Dateistand tatsächlich erfüllt ist. "
        "Gib dafür denselben requirement-Text und denselben path zurück, satisfied=true sowie "
        "einen exakten positiven Evidence-Ausschnitt aus genau dieser finalen Datei. "
        "Wenn auch nur eine Anforderung nicht positiv belegt werden kann, antworte FIX_REQUIRED."
    )
    parsed = self._review_json_call(
        [
            {"role": "system", "content": ACCEPTANCE_REVIEW_SYSTEM_PROMPT},
            {"role": "user", "content": prompt},
        ],
        ACCEPTANCE_REVIEW_MAX_OUTPUT_TOKENS,
        stage="acceptance_false_negative_recheck",
    )
    if str(parsed.get("verdict", "")).strip().upper() != "PASS":
        return {
            "verdict": "FIX_REQUIRED",
            "summary": shorten(redact(str(parsed.get("summary", ""))), 1400),
            "checks": [],
        }

    positive, problems = self._validate_acceptance_checks(parsed.get("checks", []), final_files)
    positive_keys = {
        (" ".join(str(check["requirement"]).lower().split()), str(check["path"]))
        for check in positive
    }
    missing = [
        item for item in requested
        if (" ".join(item["requirement"].lower().split()), item["path"]) not in positive_keys
    ]
    if problems or missing or len(positive_keys) != len(requested):
        details = problems[:6]
        details.extend(
            f"{item['path']}: positiver Gegenbeleg fehlt für {shorten(redact(item['requirement']), 180)}"
            for item in missing[:6]
        )
        return {
            "verdict": "FIX_REQUIRED",
            "summary": "Positive Gegenprüfung konnte nicht alle negativen Acceptance-Checks belegen.",
            "checks": positive,
            "problems": details,
        }

    return {
        "verdict": "PASS",
        "summary": "Alle bisherigen satisfied:false-Checks wurden durch validierte positive Final-State-Evidence aus derselben Datei widerlegt.",
        "checks": positive,
    }

